const M = moire, C = M.cells, d = M.gpu.device, n = C.count, F = 92;
const buf = d.createBuffer({ size: n * F * 4, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST });
const e = d.createCommandEncoder(); e.copyBufferToBuffer(C.cellBuf, 0, buf, 0, n * F * 4); d.queue.submit([e.finish()]);
await buf.mapAsync(GPUMapMode.READ); const f = new Float32Array(buf.getMappedRange().slice(0)); buf.unmap(); buf.destroy();
const k = 2.9157777693095883 / 8.747333307928765, ox = 960, oy = 540, nx = 576, ny = 180;
for (let i = 0; i < n; i++) { const o = i * F; f[o] = nx + (f[o] - ox) * k; f[o + 1] = ny + (f[o + 1] - oy) * k; f[o + 2] *= k; f[o + 3] *= k; f[o + 4] *= k; }
d.queue.writeBuffer(C.cellBuf, 0, f);
for (const s of M.matter.springs) { s.x = nx + (s.x * 1152 / 1152 - nx); }
return 'rescaled';

const M = moire, H = M.heat, d = M.gpu.device, n = H.n;
const off = H.offset(H.cur);
const buf = d.createBuffer({ size: n * 4, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST });
const e = d.createCommandEncoder(); e.copyBufferToBuffer(H.buffer, off * 4, buf, 0, n * 4); d.queue.submit([e.finish()]);
await buf.mapAsync(GPUMapMode.READ); const a = new Int32Array(buf.getMappedRange().slice(0)); buf.unmap(); buf.destroy();
let mn = 1e30, mx = -1e30, s = 0, neg = 0; for (const v of a) { if (v < mn) mn = v; if (v > mx) mx = v; s += v; if (v < 0) neg++; }
return JSON.stringify({ t: M.time(), hw: H.hw, hh: H.hh, px: H.px, R: H.R, min: mn, max: mx, sum: s, neg, alive: M.cells.alive, dish: M.dish.line() });

